if($isLoggedIn){try{require_once $_SERVER['DOCUMENT_ROOT'].'/smart-toolz/saas/bootstrap.php';$hs=saas_db()->prepare('SELECT credits FROM creator_users WHERE id=? LIMIT 1');$hs->execute([(int)$_SESSION['user_id']]);if($hr=$hs->fetch(PDO::FETCH_ASSOC))$headerCredits=(int)$hr['credits'];}catch(Throwable $e){$headerCredits=null;}}
